@js:
const data = JSON.parse(result ? result : '{}');
const list = data.list ? data.list : [];
const item = list[0] ? list[0] : {};
const playText = item.vod_play_url ? item.vod_play_url : '';
const fromText = item.vod_play_from ? item.vod_play_from : '';
const groups = String(playText).split('$$$');
const lines = String(fromText).split('$$$');
const out = [];
for (let i = 0; i < groups.length; i++) {
  const line = lines[i] ? lines[i] : '';
  for (const part of groups[i].split('#')) {
    const idx = part.indexOf('$');
    if (idx <= 0) continue;
    const name = part.slice(0, idx).trim();
    const url = part.slice(idx + 1).trim();
    if (/^https?:\/\//i.test(url)) out.push({ name, url, line });
  }
}
out;
